Flickerlessly.onReady({ selector: '.mini-toc-wrapper', success: function(miniTocWrapper) { var miniToc = miniTocWrapper.querySelector('.mini-toc'); // console.log('Announcements: Flickerlessly found mini-toc element:', miniToc); let announcementsContainer = null; function createAnnouncementsSection() { // console.log('Announcements: createAnnouncementsSection function called'); // Find all sibling divs const siblings = Array.from(miniToc.parentNode.children); const announcementDivs = []; // console.log('Announcements: Found', siblings.length, 'siblings of mini-toc'); siblings.forEach(sibling => { // Skip if it's the mini-toc itself if (sibling === miniToc || sibling.classList.contains('mini-toc')) { return; } // Skip if it has the redesigned section classes if (sibling.classList.contains('redesign-events-section') || sibling.classList.contains('redesign-video-section')) { return; } // Skip if it contains the events or video sections by checking for inner IDs const hasEventsSection = sibling.querySelector('#recs-event-promos'); const hasVideoSection = sibling.querySelector('#recs-video-clips-promos'); if (hasEventsSection || hasVideoSection) { return; } // Skip if it's already been processed as announcement content if (sibling.classList.contains('announcement-content')) { return; } // Add a class to identify these as announcement content if (sibling.tagName === 'DIV' && sibling.innerHTML.trim()) { // console.log('Announcements: Adding sibling to announcements:', sibling); sibling.classList.add('announcement-content'); announcementDivs.push(sibling); } }); // console.log('Announcements: Total items to add:', announcementDivs.length); if (announcementDivs.length > 0) { // Create announcements container if it doesn't exist if (!announcementsContainer) { // console.log('Announcements: Creating new announcements container'); announcementsContainer = document.createElement('div'); announcementsContainer.id = 'recs-announcements'; announcementsContainer.className = 'announc